// GENERATED by scripts/import_malloy.mjs from the malloy-render library — do not edit.
// Only the imports are rewritten (remotion frame hooks -> ../remotionShim, google fonts ->
// ../googleFonts, zod schema removed since its fields now live in the adapter's params).
import React from "react";
import { useCurrentFrame, useVideoConfig, AbsoluteFill, random, interpolate } from '../remotionShim';
import { makeLoadFont } from '../googleFonts';
const loadInter = makeLoadFont('Inter');

const { fontFamily } = loadInter();



export type MessyPhysicsThrowProps = Record<string, any>;

const MessyPhysicsThrow: React.FC<MessyPhysicsThrowProps> = ({
  backgroundColor = "#f0f0f0",
  transparentBackground = false,
  durationInSeconds = 15, 
  wordsToThrow = [
    { text: "Thank", color: "#FF3366" },
    { text: "you", color: "#33CCFF" },
    { text: "for", color: "#FF9933" },
    { text: "11,000", color: "#9933FF" },
    { text: "motion", color: "#33FF99" },
    { text: "graphics", color: "#FF3333" },
    { text: "exported", color: "#3366FF" }
  ],
  fontSize = 393,
  gravity = 3500,
  throwForce = 4000,
  horizontalSpread = 600,
}) => {
  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  // Handle transparent background safety
  const bgColor = transparentBackground ? `${backgroundColor}00` : backgroundColor;

  // Filter out any completely empty strings from the list
  const words = wordsToThrow.filter((wordObj) => wordObj.text.trim() !== "");

  // Calculate dynamic delays so each word's letters wait for the previous word to finish falling
  let cumulativeDelay = 0;
  
  const lettersData = words.flatMap((wordObj, wordIndex) => {
    const { text: word, color: wordColor } = wordObj;
    
    // Base Vertical Force for the word to determine the delay for the NEXT word
    const baseVy = interpolate(random(wordIndex + "baseVy"), [0, 1], [throwForce * 0.85, throwForce * 1.15]);
    
    // Calculate flight time using physics: flightTime = (2 * initialVelocity) / gravity
    const flightTime = (2 * baseVy) / gravity;
    const wordStartDelay = cumulativeDelay;
    cumulativeDelay += flightTime; // Add flight time for the NEXT word's start delay

    // Process each letter independently
    return word.split("").flatMap((char, charIndex) => {
      // Skip empty spaces
      if (char.trim() === "") return [];

      const seed = `${wordIndex}_${charIndex}`;
      
      // Individual letter vertical force (messier range)
      const vy = interpolate(random(seed + "vy"), [0, 1], [throwForce * 0.7, throwForce * 1.3]);
      
      // Horizontal scatter
      const vx = interpolate(
        random(seed + "vxOffset"), 
        [0, 1], 
        [-horizontalSpread / 2, horizontalSpread / 2]
      );

      // Attempt to maintain a very loose word structure at start before exploding
      const charXOffset = (charIndex - (word.length - 1) / 2) * (fontSize * 0.5);
      const randomXOffset = interpolate(random(seed + "x"), [0, 1], [-100, 100]);
      
      const startX = (width / 2) + charXOffset + randomXOffset;
      const startY = height + fontSize * 1.5; // Start fully off-screen at the bottom

      // Rotations - increased for letters compared to whole words for extra messiness
      const rotSpeed = interpolate(random(seed + "rotSpeed"), [0, 1], [-240, 240]); 
      const initialRot = interpolate(random(seed + "irot"), [0, 1], [-90, 90]);

      return [{
        char,
        color: wordColor,
        seed,
        vy,
        vx,
        startX,
        startY,
        startDelay: wordStartDelay,
        rotSpeed,
        initialRot
      }];
    });
  });

  return (
    <AbsoluteFill style={{ backgroundColor: bgColor, fontFamily, overflow: "hidden" }}>
      {lettersData.map(({ char, color, vy, vx, startX, startY, startDelay, rotSpeed, initialRot }, i) => {
        // 1. Time & Staggering based on physics calculation
        let t = (frame / fps) - startDelay;
        if (t < 0) t = 0; // Hold at starting position until the previous word finishes

        // 2. Projectile Physics Equations (y decreases as it goes up on screen)
        const x = startX + vx * t;
        const y = startY - (vy * t) + (0.5 * gravity * t * t);

        // 3. Rotation applied to individual letters
        const rotation = initialRot + rotSpeed * t;

        return (
          <div
            key={i}
            style={{
              position: "absolute",
              left: x,
              top: y,
              fontSize: `${fontSize}px`,
              color: color,
              fontWeight: 800, 
              lineHeight: 1,
              userSelect: "none",
              whiteSpace: "nowrap",
              transform: `translate(-50%, -50%) rotate(${rotation}deg)`,
              transition: "none", // Critical for remotion anti-flicker
            }}
          >
            {char}
          </div>
        );
      })}
    </AbsoluteFill>
  );
};

export default MessyPhysicsThrow;